-- Properties (real estate listings) and the log of properties shared with contacts

create table "public"."properties" (
    "id" bigint generated by default as identity primary key,
    "title" text not null,
    "property_type" text,
    "operation" text,
    "price" bigint,
    "currency" text,
    "address" text,
    "neighborhood" text,
    "city" text,
    "bedrooms" smallint,
    "bathrooms" smallint,
    "built_area" numeric,
    "land_area" numeric,
    "parking_spaces" smallint,
    "agency" text,
    "description" text,
    "sales_id" bigint,
    "created_at" timestamp with time zone not null default now(),
    "updated_at" timestamp with time zone not null default now()
);

create table "public"."property_shares" (
    "id" bigint generated by default as identity primary key,
    "property_id" bigint not null,
    "contact_id" bigint not null,
    "shared_at" date not null default current_date,
    "comment" text,
    "sales_id" bigint,
    "created_at" timestamp with time zone not null default now()
);

alter table "public"."properties"
    add constraint "properties_sales_id_fkey" foreign key ("sales_id") references "public"."sales"("id");

alter table "public"."property_shares"
    add constraint "property_shares_property_id_fkey" foreign key ("property_id") references "public"."properties"("id") on update cascade on delete cascade;

alter table "public"."property_shares"
    add constraint "property_shares_contact_id_fkey" foreign key ("contact_id") references "public"."contacts"("id") on update cascade on delete cascade;

alter table "public"."property_shares"
    add constraint "property_shares_sales_id_fkey" foreign key ("sales_id") references "public"."sales"("id");

create index "property_shares_property_id_idx" on "public"."property_shares" using btree ("property_id");
create index "property_shares_contact_id_idx" on "public"."property_shares" using btree ("contact_id");

alter table "public"."properties" enable row level security;
alter table "public"."property_shares" enable row level security;

create policy "Enable read access for authenticated users" on "public"."properties" for select to authenticated using (true);
create policy "Enable insert for authenticated users only" on "public"."properties" for insert to authenticated with check (true);
create policy "Enable update for authenticated users only" on "public"."properties" for update to authenticated using (true) with check (true);
create policy "Enable delete for authenticated users only" on "public"."properties" for delete to authenticated using (true);

create policy "Enable read access for authenticated users" on "public"."property_shares" for select to authenticated using (true);
create policy "Enable insert for authenticated users only" on "public"."property_shares" for insert to authenticated with check (true);
create policy "Enable update for authenticated users only" on "public"."property_shares" for update to authenticated using (true) with check (true);
create policy "Enable delete for authenticated users only" on "public"."property_shares" for delete to authenticated using (true);

grant all on table "public"."properties" to anon;
grant all on table "public"."properties" to authenticated;
grant all on table "public"."properties" to service_role;

grant all on table "public"."property_shares" to anon;
grant all on table "public"."property_shares" to authenticated;
grant all on table "public"."property_shares" to service_role;

grant all on sequence "public"."properties_id_seq" to anon;
grant all on sequence "public"."properties_id_seq" to authenticated;
grant all on sequence "public"."properties_id_seq" to service_role;

grant all on sequence "public"."property_shares_id_seq" to anon;
grant all on sequence "public"."property_shares_id_seq" to authenticated;
grant all on sequence "public"."property_shares_id_seq" to service_role;
